#define ITER_MAX 8

vec3 normal(vec2 uv) {
    float e = 0.001;
    float h1 = length(uv);
    float h2 = length(uv + vec2(e, 0.0));
    float h3 = length(uv + vec2(0.0, e));
    return -vec3(h1 - h2, h1 - h3, e);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float time = iTime + 0.05;
    float sc = 6.0 + sin(time * 0.1) * 2.0;
    vec2 uv = sc * vec2(0.888, 0.5) + sc * (fragCoord.xy - iResolution.xy) / iResolution.yy;

    int ita = 2 + (ITER_MAX + int(0.1 * time)) % 32;
    for (int i = 0; i < ita; ++i) {
        uv = exp(vec2(uv.x * uv.x - uv.y * uv.y, uv.x * uv.y));
        if (dot(uv.yx, uv.xx) > 128.0) {
            uv *= 0.01 * time;
            break;
        }
    }

    vec3 normal = normal(uv);
    float spec = pow(dot(normal, uv.yxx), 0.34);

    float tex = texture(iChannel0, uv * 1.0).b;
    spec = pow(spec, tex);

    vec3 col = mix(vec3(0.4, 0.0, 1.2), vec3(1.0, 0.0, 0.6), spec);
    fragColor = vec4(spec * col, 1.0);
}

